    config = resolveConfig(argv.slice(1), process.env);
  } catch (err) {
    console.error(`syncbox: ${err.message}`);
    process.exitCode = 1;
    return;
  }

  if (command === 'push') {
    try {
      const result = await push.run(config);
      for (const key of result.uploaded) {
        console.log(`uploaded ${key}`);
