  const beforeEntries = fs.readdirSync(dir).sort();
  const beforeContents = {
    'a.txt': fs.readFileSync(path.join(dir, 'a.txt'), 'utf8'),
    'local-only.txt': fs.readFileSync(path.join(dir, 'local-only.txt'), 'utf8'),
